-- Disposable fixtures. This transaction does not send network notifications.
begin;
update private.push_dispatch set last_wake = clock_timestamp() + interval '1 day';
do $$
declare a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); c uuid := gen_random_uuid(); d uuid := gen_random_uuid(); cid uuid := gen_random_uuid(); gid uuid := gen_random_uuid(); person uuid;
begin
  foreach person in array array[a,b,c,d] loop
    insert into auth.users(id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
    values(person, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'qa27_' || left(replace(person::text,'-',''),16) || '@chat.local', '', clock_timestamp(), '{"provider":"email","providers":["email"]}', '{}', clock_timestamp(), clock_timestamp());
  end loop;
  update public.profiles set is_pro = true where id = d;
  insert into public.conversations(id,member_a,member_b,created_by) values(cid,least(a,b),greatest(a,b),a);
  insert into public.conversations(id,kind,title,created_by) values(gid,'group','Push QA',a);
  insert into public.conversation_members(conversation_id,user_id) values(gid,a),(gid,b),(gid,c);
  perform set_config('bitchat.qa_a',a::text,true); perform set_config('bitchat.qa_b',b::text,true);
  perform set_config('bitchat.qa_c',c::text,true); perform set_config('bitchat.qa_d',d::text,true);
  perform set_config('bitchat.qa_cid',cid::text,true); perform set_config('bitchat.qa_gid',gid::text,true);
end $$;
select set_config('request.jwt.claim.sub',current_setting('bitchat.qa_b'),true);
set local role authenticated;
do $$ begin
  perform public.register_push_subscription('https://fcm.googleapis.com/fcm/send/qa27b','B'||repeat('A',86),repeat('A',22));
  perform public.register_push_subscription('https://fcm.googleapis.com/fcm/send/qa27b','B'||repeat('A',86),repeat('A',22));
  begin perform public.register_push_subscription('https://127.0.0.1/private','B'||repeat('A',86),repeat('A',22)); raise exception 'Unsafe endpoint accepted.'; exception when invalid_parameter_value then null; end;
  begin perform public.register_push_subscription('https://fcm.googleapis.com:8443/path','B'||repeat('A',86),repeat('A',22)); raise exception 'Unsafe port accepted.'; exception when invalid_parameter_value then null; end;
  begin perform public.register_push_subscription('https://fcm.googleapis.com/fcm/send/bad','invalid',repeat('A',22)); raise exception 'Invalid key accepted.'; exception when invalid_parameter_value then null; end;
  begin perform public.push_server_config(repeat('0',64)); raise exception 'Browser read server configuration.'; exception when insufficient_privilege then null; end;
  begin perform public.claim_push_jobs(repeat('0',64)); raise exception 'Browser claimed delivery work.'; exception when insufficient_privilege then null; end;
  begin perform private.wake_push_worker(true); raise exception 'Browser invoked the worker.'; exception when insufficient_privilege then null; end;
  begin perform (select count(*) from private.push_subscriptions); raise exception 'Browser read device endpoints.'; exception when insufficient_privilege then null; end;
end $$;
reset role;
do $$
declare a uuid := current_setting('bitchat.qa_a')::uuid; b uuid := current_setting('bitchat.qa_b')::uuid; c uuid := current_setting('bitchat.qa_c')::uuid; d uuid := current_setting('bitchat.qa_d')::uuid;
  cid uuid := current_setting('bitchat.qa_cid')::uuid; gid uuid := current_setting('bitchat.qa_gid')::uuid; first_id uuid; second_id uuid; group_message_id uuid;
  worker_secret text; job record; next_job record; i integer;
begin
  select decrypted_secret into worker_secret from vault.decrypted_secrets where name = 'bitchat_push_worker_secret';
  assert (select count(*)=1 from private.push_subscriptions where user_id=b), 'Registration is idempotent.';
  assert not has_function_privilege('anon','public.register_push_subscription(text,text,text)','EXECUTE'), 'Anonymous registration is denied.';
  assert not has_function_privilege('authenticated','public.push_server_config(text)','EXECUTE'), 'Server signing keys are not a browser RPC.';
  assert not has_table_privilege('authenticated','private.push_jobs','SELECT'), 'The queue is private.';
  assert public.push_server_config(repeat('0',64)) is null, 'Wrong worker credentials reveal nothing.';
  perform set_config('request.jwt.claim.sub',a::text,true);
  perform public.unregister_push_subscription('https://fcm.googleapis.com/fcm/send/qa27b');
  assert (select count(*)=1 from private.push_subscriptions where user_id=b), 'Another user cannot unsubscribe a device.';
  begin perform public.register_push_subscription('https://fcm.googleapis.com/fcm/send/qa27b','B'||repeat('A',86),repeat('A',22)); raise exception 'Device was stolen.'; exception when insufficient_privilege then null; end;
  perform public.register_push_subscription('https://fcm.googleapis.com/fcm/send/qa27a','B'||repeat('A',86),repeat('A',22));
  perform set_config('request.jwt.claim.sub',c::text,true); perform public.register_push_subscription('https://fcm.googleapis.com/fcm/send/qa27c','B'||repeat('A',86),repeat('A',22));
  perform set_config('request.jwt.claim.sub',d::text,true); perform public.register_push_subscription('https://fcm.googleapis.com/fcm/send/qa27d','B'||repeat('A',86),repeat('A',22));
  perform set_config('request.jwt.claim.sub',a::text,true);
  insert into public.messages(conversation_id,user_id,content) values(cid,a,'💋 A kiss for you') returning id into first_id;
  assert (select count(*)=1 from private.push_jobs where conversation_id=cid), 'One receiver gets one delivery job.';
  assert not private.push_eligible(a,cid,first_id), 'Senders do not receive their own alerts.';
  assert not private.push_eligible(d,cid,first_id), 'Pro does not grant outsider delivery access.';
  select * into job from public.claim_push_jobs(worker_secret) where conversation_id=cid;
  assert job.lease is not null and job.user_id=b, 'Claims are leased to the intended device.';
  assert (select count(*)=0 from public.claim_push_jobs(worker_secret)), 'A concurrent worker cannot claim a live lease.';
  insert into public.messages(conversation_id,user_id,content) values(cid,a,'🫂 A hug for you') returning id into second_id;
  assert (select count(*)=1 from private.push_jobs where conversation_id=cid), 'Messages coalesce per conversation and device.';
  perform public.finish_push_job(worker_secret,job.subscription_id,cid,first_id,job.lease,201);
  assert (select message_id=second_id from private.push_jobs where conversation_id=cid), 'A delayed success cannot delete a newer message.';
  select * into next_job from public.claim_push_jobs(worker_secret) where conversation_id=cid;
  assert next_job.lease<>job.lease, 'A new message receives a new lease.';
  perform public.finish_push_job(worker_secret,next_job.subscription_id,cid,second_id,next_job.lease,503);
  assert (select lease is null and next_attempt>clock_timestamp() and attempts=1 from private.push_jobs where conversation_id=cid), 'Transient failures retry with backoff.';
  assert (select count(*)=0 from public.claim_push_jobs(worker_secret)), 'Backoff avoids an immediate retry storm.';
  update private.push_jobs set next_attempt=clock_timestamp() where conversation_id=cid;
  select * into job from public.claim_push_jobs(worker_secret) where conversation_id=cid;
  perform public.finish_push_job(worker_secret,job.subscription_id,cid,second_id,job.lease,201);
  assert (select count(*)=0 from private.push_jobs where conversation_id=cid), 'Successful delivery removes the queue item.';
  perform set_config('request.jwt.claim.sub',b::text,true); perform public.set_chat_archived(cid,true);
  perform set_config('request.jwt.claim.sub',a::text,true);
  insert into public.messages(conversation_id,user_id,content) values(cid,a,'Archived alert');
  assert (select count(*)=0 from private.push_jobs where conversation_id=cid), 'Archived chats are quiet.';
  perform set_config('request.jwt.claim.sub',b::text,true); perform public.set_chat_archived(cid,false); perform public.mark_read_through(cid,second_id);
  assert not private.push_eligible(b,cid,second_id), 'Read messages are not redelivered.';
  perform public.clear_chat(cid);
  assert not private.push_eligible(b,cid,first_id), 'Cleared history cannot generate alerts.';
  perform set_config('request.jwt.claim.sub',a::text,true);
  insert into public.messages(conversation_id,user_id,content,kind) values(cid,a,'🤍 I miss you','miss') returning id into first_id;
  assert (select count(*)=1 from private.push_jobs where conversation_id=cid), 'A new message after clearing still alerts.';
  select * into job from public.claim_push_jobs(worker_secret) where conversation_id=cid;
  perform public.finish_push_job(worker_secret,job.subscription_id,cid,first_id,job.lease,410);
  assert not exists(select 1 from private.push_subscriptions where user_id=b), 'An expired endpoint is removed.';
  perform set_config('request.jwt.claim.sub',b::text,true); perform public.register_push_subscription('https://fcm.googleapis.com/fcm/send/qa27b2','B'||repeat('A',86),repeat('A',22));
  perform set_config('request.jwt.claim.sub',a::text,true);
  insert into public.messages(conversation_id,user_id,content) values(gid,a,'A group hello') returning id into group_message_id;
  assert (select count(*)=2 from private.push_jobs where conversation_id=gid), 'Current group receivers get jobs.';
  assert not private.push_eligible(d,gid,group_message_id), 'Group outsiders remain excluded.';
  perform set_config('request.jwt.claim.sub',b::text,true); perform public.leave_group(gid);
  assert not private.push_eligible(b,gid,group_message_id), 'Leaving revokes queued group delivery.';
  perform public.claim_push_jobs(worker_secret);
  assert (select count(*)=1 from private.push_jobs where conversation_id=gid), 'Ineligible jobs are pruned before sending.';
  perform set_config('request.jwt.claim.sub',a::text,true); delete from public.messages where id=group_message_id;
  assert not exists(select 1 from private.push_jobs where conversation_id=gid), 'Deleted messages remove pending notifications.';
  perform set_config('request.jwt.claim.sub',b::text,true); perform public.set_block(a,true);
  assert not private.push_eligible(b,cid,first_id), 'Blocking suppresses delivery.';
  perform public.set_block(a,false); perform public.unregister_push_subscription('https://fcm.googleapis.com/fcm/send/qa27b2');
  assert not exists(select 1 from private.push_subscriptions where user_id=b), 'Disabling removes the current device.';
  for i in 1..10 loop perform public.register_push_subscription('https://fcm.googleapis.com/fcm/send/qa27limit'||i,'B'||repeat('A',86),repeat('A',22)); end loop;
  begin perform public.register_push_subscription('https://fcm.googleapis.com/fcm/send/qa27limit11','B'||repeat('A',86),repeat('A',22)); raise exception 'Device limit was bypassed.'; exception when raise_exception then if sqlerrm<>'Notification device limit reached.' then raise; end if; end;
  assert (select count(*)=10 from private.push_subscriptions where user_id=b), 'Device storage is bounded.';
end $$;
rollback;
select 'WEB_PUSH_SQL_PASS' as result;
